SELECT investigation_id, run_id, fixture_id, CASE WHEN http_status = '\\N' THEN NULL ELSE CAST(http_status AS BIGINT) END AS http_status, CASE WHEN duration_seconds = '\\N' THEN NULL ELSE CAST(duration_seconds AS DECIMAL(20,6)) END AS duration_seconds, CASE WHEN schema_valid = '\\N' THEN NULL ELSE CAST(schema_valid AS BIGINT) END AS schema_valid, CASE WHEN quality_pass = '\\N' THEN NULL ELSE CAST(quality_pass AS BIGINT) END AS quality_pass, CASE WHEN prompt_tokens = '\\N' THEN NULL ELSE CAST(prompt_tokens AS BIGINT) END AS prompt_tokens, CASE WHEN completion_tokens = '\\N' THEN NULL ELSE CAST(completion_tokens AS BIGINT) END AS completion_tokens, CASE WHEN total_tokens = '\\N' THEN NULL ELSE CAST(total_tokens AS BIGINT) END AS total_tokens FROM nextwise.evaluation_cases;
